import io
from collections import OrderedDict

import pytest

import xmltodict


# ---------- parse: basics ----------

def test_parse_readme_example():
    xml = """
    <mydocument has="an attribute">
      <and>
        <many>elements</many>
        <many>more elements</many>
      </and>
      <plus a="complex">
        element as well
      </plus>
    </mydocument>
    """
    assert xmltodict.parse(xml) == {
        "mydocument": {
            "@has": "an attribute",
            "and": {"many": ["elements", "more elements"]},
            "plus": {"@a": "complex", "#text": "element as well"},
        }
    }


def test_parse_empty_element_is_none():
    assert xmltodict.parse("<a/>") == {"a": None}


def test_parse_bytes_input():
    assert xmltodict.parse(b"<a>hi</a>") == {"a": "hi"}


def test_parse_file_like_input():
    assert xmltodict.parse(io.BytesIO(b"<a><b>1</b></a>")) == {"a": {"b": "1"}}


def test_parse_generator_input():
    def gen():
        yield "<a><b>"
        yield "1</b></a>"
    assert xmltodict.parse(gen()) == {"a": {"b": "1"}}


def test_parse_xml_attribs_false():
    assert xmltodict.parse('<a x="1">t</a>', xml_attribs=False) == {"a": "t"}


def test_parse_custom_attr_prefix_and_cdata_key():
    result = xmltodict.parse('<a x="1">t</a>', attr_prefix="$", cdata_key="_")
    assert result == {"a": {"$x": "1", "_": "t"}}


def test_parse_strip_whitespace_default():
    assert xmltodict.parse("<a>  x  </a>") == {"a": "x"}


def test_parse_strip_whitespace_false():
    assert xmltodict.parse("<a> x </a>", strip_whitespace=False) == {"a": " x "}


def test_parse_dict_constructor():
    result = xmltodict.parse("<a><b>1</b></a>", dict_constructor=OrderedDict)
    assert isinstance(result, OrderedDict)
    assert result == {"a": {"b": "1"}}


def test_parse_entities_disabled_raises():
    xml = '<!DOCTYPE a [<!ENTITY e "x">]><a>&e;</a>'
    with pytest.raises(ValueError):
        xmltodict.parse(xml)


# ---------- namespaces ----------

NS_XML = """
<root xmlns="http://defaultns.com/"
      xmlns:a="http://a.com/"
      xmlns:b="http://b.com/">
  <x>1</x>
  <a:y>2</a:y>
  <b:z>3</b:z>
</root>
"""


def test_namespaces_not_processed_by_default():
    xml = '<root xmlns:a="http://a.com/"><a:y>2</a:y></root>'
    assert xmltodict.parse(xml) == {
        "root": {"@xmlns:a": "http://a.com/", "a:y": "2"}
    }


def test_process_namespaces_expands():
    result = xmltodict.parse(NS_XML, process_namespaces=True)
    result["http://defaultns.com/:root"].pop("@xmlns", None)
    assert result == {
        "http://defaultns.com/:root": {
            "http://defaultns.com/:x": "1",
            "http://a.com/:y": "2",
            "http://b.com/:z": "3",
        }
    }


def test_process_namespaces_collapse_and_skip():
    namespaces = {"http://defaultns.com/": None, "http://a.com/": "ns_a"}
    result = xmltodict.parse(NS_XML, process_namespaces=True,
                             namespaces=namespaces)
    result["root"].pop("@xmlns", None)
    assert result == {
        "root": {"x": "1", "ns_a:y": "2", "http://b.com/:z": "3"}
    }


def test_process_namespaces_custom_separator():
    xml = '<root xmlns:a="http://a.com/"><a:y>2</a:y></root>'
    result = xmltodict.parse(xml, process_namespaces=True,
                             namespace_separator="|",
                             namespaces={"http://a.com/": "ns_a"})
    assert result["root"]["ns_a|y"] == "2"


# ---------- streaming ----------

def test_streaming_item_depth_2():
    items = []

    def cb(path, item):
        items.append((list(path), item))
        return True

    result = xmltodict.parse('<a prop="x"><b>1</b><b>2</b></a>',
                             item_depth=2, item_callback=cb)
    assert result is None
    assert items == [
        ([("a", {"prop": "x"}), ("b", None)], "1"),
        ([("a", {"prop": "x"}), ("b", None)], "2"),
    ]


def test_streaming_dict_items():
    items = []

    def cb(path, item):
        items.append(item)
        return True

    xmltodict.parse("<a><b><n>x</n></b><b><n>y</n></b></a>",
                    item_depth=2, item_callback=cb)
    assert items == [{"n": "x"}, {"n": "y"}]


def test_streaming_callback_false_interrupts():
    calls = []

    def cb(path, item):
        calls.append(item)
        return False

    with pytest.raises(xmltodict.ParsingInterrupted):
        xmltodict.parse("<a><b>1</b><b>2</b></a>",
                        item_depth=2, item_callback=cb)
    assert calls == ["1"]


# ---------- force_cdata / force_list ----------

CDATA_XML = "<a><b>data1</b><c>data2</c><d>data3</d></a>"


def test_force_cdata_tuple():
    assert xmltodict.parse(CDATA_XML, force_cdata=("b", "d")) == {
        "a": {"b": {"#text": "data1"}, "c": "data2", "d": {"#text": "data3"}}
    }


def test_force_cdata_true():
    assert xmltodict.parse(CDATA_XML, force_cdata=True) == {
        "a": {"b": {"#text": "data1"}, "c": {"#text": "data2"},
              "d": {"#text": "data3"}}
    }


def test_force_cdata_callable():
    def f(path, key, value):
        return key in ["b", "d"] and len(value) > 4

    assert xmltodict.parse(CDATA_XML, force_cdata=f) == {
        "a": {"b": {"#text": "data1"}, "c": "data2", "d": {"#text": "data3"}}
    }


LIST_XML = "<a><b>data1</b><b>data2</b><c>data3</c></a>"


def test_force_list_tuple():
    assert xmltodict.parse(LIST_XML, force_list=("b",)) == {
        "a": {"b": ["data1", "data2"], "c": "data3"}
    }


def test_force_list_single_element():
    assert xmltodict.parse("<a><b>1</b></a>", force_list=("b",)) == {
        "a": {"b": ["1"]}
    }


def test_force_list_true():
    assert xmltodict.parse(LIST_XML, force_list=True) == {
        "a": [{"b": ["data1", "data2"], "c": ["data3"]}]
    }


def test_force_list_callable():
    def f(path, key, value):
        return key in ["b"] and isinstance(value, str)

    assert xmltodict.parse(LIST_XML, force_list=f) == {
        "a": {"b": ["data1", "data2"], "c": "data3"}
    }


# ---------- postprocessor ----------

def test_postprocessor():
    def pp(path, key, value):
        try:
            return key + ":int", int(value)
        except (ValueError, TypeError):
            return key, value

    result = xmltodict.parse("<a><b>1</b><b>2</b><b>x</b></a>", postprocessor=pp)
    assert result == {"a": {"b:int": [1, 2], "b": "x"}}


# ---------- comments ----------

def test_comments_ignored_by_default():
    assert xmltodict.parse("<a><!-- hi --><b>1</b></a>") == {"a": {"b": "1"}}


def test_process_comments():
    xml = ("<a><b><!-- b comment --><c><!-- c comment -->1</c>"
           "<d>2</d></b></a>")
    assert xmltodict.parse(xml, process_comments=True) == {
        "a": {
            "b": {
                "#comment": "b comment",
                "c": {"#comment": "c comment", "#text": "1"},
                "d": "2",
            }
        }
    }


def test_process_comments_no_strip():
    result = xmltodict.parse("<a><!-- hi --><b>1</b></a>",
                             process_comments=True, strip_whitespace=False)
    assert result == {"a": {"#comment": " hi ", "b": "1"}}


def test_process_comments_custom_key():
    result = xmltodict.parse("<a><!--hi--><b>1</b></a>",
                             process_comments=True, comment_key="_c")
    assert result == {"a": {"_c": "hi", "b": "1"}}


# ---------- unparse ----------

DECL = '<?xml version="1.0" encoding="utf-8"?>\n'


def test_unparse_simple():
    assert xmltodict.unparse({"a": "x"}) == DECL + "<a>x</a>"


def test_unparse_readme_pretty():
    d = {"response": {"status": "good",
                      "last_updated": "2014-02-16T23:10:12Z"}}
    assert xmltodict.unparse(d, pretty=True) == (
        DECL + "<response>\n"
        "\t<status>good</status>\n"
        "\t<last_updated>2014-02-16T23:10:12Z</last_updated>\n"
        "</response>"
    )


def test_unparse_attrs_and_text_roundtrip():
    d = {"text": {"@color": "red", "@stroke": "2", "#text": "This is a test"}}
    xml = xmltodict.unparse(d)
    assert xmltodict.parse(xml) == d


def test_unparse_custom_prefix_and_cdata_key():
    d = {"t": {"$c": "red", "_": "hi"}}
    xml = xmltodict.unparse(d, attr_prefix="$", cdata_key="_",
                            full_document=False)
    assert xml == '<t c="red">hi</t>'


def test_unparse_full_document_false():
    assert xmltodict.unparse({"a": "x"}, full_document=False) == "<a>x</a>"


def test_unparse_short_empty_elements():
