                             full_document=False) == "<a><c>x</c></a>"


def test_unparse_placeholder_list():
    assert xmltodict.unparse({"a": {"b": [""]}},
                             full_document=False) == "<a><b></b></a>"


def test_unparse_bool_values():
    assert xmltodict.unparse({"a": {"b": True, "c": False}},
                             full_document=False) == "<a><b>true</b><c>false</c></a>"


def test_unparse_numbers():
    assert xmltodict.unparse({"a": 5}, full_document=False) == "<a>5</a>"


def test_unparse_escapes_text():
    assert xmltodict.unparse({"a": "<&>"}, full_document=False) == "<a>&lt;&amp;&gt;</a>"


def test_unparse_nested_lists_without_expand_iter():
    d = {"line": {"points": [[1, 5], [2, 6]]}}
    assert xmltodict.unparse(d, pretty=True) == (
        DECL + "<line>\n"
        "\t<points>[1, 5]</points>\n"
        "\t<points>[2, 6]</points>\n"
        "</line>"
    )


def test_unparse_expand_iter():
    d = {"line": {"points": [[1, 5], [2, 6]]}}
    assert xmltodict.unparse(d, pretty=True, expand_iter="coord") == (
        DECL + "<line>\n"
        "\t<points>\n"
        "\t\t<coord>1</coord>\n"
