        "\t</points>\n"
        "\t<points>\n"
        "\t\t<coord>2</coord>\n"
        "\t\t<coord>6</coord>\n"
        "\t</points>\n"
        "</line>"
    )


def test_unparse_pretty_int_indent():
    assert xmltodict.unparse({"a": {"b": "1"}}, pretty=True, indent=2,
                             full_document=False) == "<a>\n  <b>1</b>\n</a>"


def test_unparse_pretty_custom_newl():
