import io
from collections import OrderedDict

import pytest
import xmltodict


XML_DECL = '<?xml version="1.0" encoding="utf-8"?>\n'


def _without_xmlns(doc):
    """Remove the '@xmlns' declaration entry from each root element dict."""
    out = {}
    for k, v in doc.items():
        if isinstance(v, dict):
            v = {kk: vv for kk, vv in v.items() if kk != "@xmlns"}
        out[k] = v
    return out


def test_readme_basic_example():
    doc = xmltodict.parse("""
    <mydocument has="an attribute">
      <and>
        <many>elements</many>
        <many>more elements</many>
      </and>
      <plus a="complex">
        element as well
      </plus>
    </mydocument>
    """)
    assert doc == {
        "mydocument": {
            "@has": "an attribute",
            "and": {"many": ["elements", "more elements"]},
            "plus": {"@a": "complex", "#text": "element as well"},
        }
    }


def test_empty_element_is_none():
    assert xmltodict.parse("<a/>") == {"a": None}


def test_attributes_only():
    assert xmltodict.parse('<a x="1"/>') == {"a": {"@x": "1"}}


def test_xml_attribs_false():
    assert xmltodict.parse('<a x="1">t</a>', xml_attribs=False) == {"a": "t"}


def test_attr_prefix_and_cdata_key():
    doc = xmltodict.parse('<a x="1">t</a>', attr_prefix="$", cdata_key="_t")
    assert doc == {"a": {"$x": "1", "_t": "t"}}


def test_bytes_and_file_and_generator_input():
    assert xmltodict.parse(b"<a>1</a>") == {"a": "1"}
    assert xmltodict.parse(io.BytesIO(b"<a>1</a>")) == {"a": "1"}

    def gen():
        yield b"<a><b>1"
        yield b"</b></a>"

    assert xmltodict.parse(gen()) == {"a": {"b": "1"}}


NS_XML = """
<root xmlns="http://defaultns.com/"
      xmlns:a="http://a.com/"
      xmlns:b="http://b.com/">
