    doc = xmltodict.parse('<a xmlns:n="http://n/"><n:b>1</n:b></a>')
    assert doc == {"a": {"@xmlns:n": "http://n/", "n:b": "1"}}


def test_namespace_separator():
    xml = '<r xmlns:a="http://a.com/"><a:y>2</a:y></r>'
    doc = xmltodict.parse(xml, process_namespaces=True,
                          namespace_separator="|")
    assert _without_xmlns(doc) == {"r": {"http://a.com/|y": "2"}}


