def test_postprocessor():
    def pp(path, key, value):
        try:
            return key + ':int', int(value)
        except (ValueError, TypeError):
            return key, value

    assert xmltodict.parse('<a><b>1</b><b>2</b><b>x</b></a>',
                           postprocessor=pp) == {
        'a': {'b:int': [1, 2], 'b': 'x'}}


def test_parse_bytes_file_and_generator():
    expected = {'a': {'b': '1'}}
    assert xmltodict.parse(b'<a><b>1</b></a>') == expected
    assert xmltodict.parse(io.BytesIO(b'<a><b>1</b></a>')) == expected

    def gen():
        yield b'<a><b>'
        yield b'1</b></a>'

    assert xmltodict.parse(gen()) == expected


def test_parse_with_encoding():
