    assert xmltodict.parse(xml, encoding='latin-1') == {'a': 'é'}


def test_streaming_item_callback():
    seen = []

    def cb(path, item):
        seen.append((list(path), item))
        return True

    result = xmltodict.parse('<a prop="x"><b>1</b><b>2</b></a>',
                             item_depth=2, item_callback=cb)
    assert result is None
    assert seen == [
        ([('a', {'prop': 'x'}), ('b', None)], '1'),
        ([('a', {'prop': 'x'}), ('b', None)], '2'),
    ]


def test_streaming_callback_false_interrupts():
