import io

import pytest
import xmltodict


def test_handler_initial_data_is_empty_list():
    handler = xmltodict._DictSAXHandler()
    assert handler.data == []


def test_handler_accepts_plain_dict_attrs():
    handler = xmltodict._DictSAXHandler()
    handler.startElement('a', {'x': '1'})
    handler.endElement('a')
    assert handler.item == {'a': {'@x': '1'}}


def test_postprocessor_receives_path_for_attributes():
    calls = []

    def pp(path, key, value):
        calls.append((list(path), key, value))
        return key, value

    xmltodict.parse('<a x="1"/>', postprocessor=pp)
    assert calls == [
        ([('a', {'x': '1'})], '@x', '1'),
        ([('a', {'x': '1'})], 'a', {'@x': '1'}),
    ]


def test_postprocessor_receives_path_for_elements():
    calls = []

    def pp(path, key, value):
        calls.append((list(path), key, value))
        return key, value

    xmltodict.parse('<a><b>1</b></a>', postprocessor=pp)
    assert calls == [
        ([('a', None), ('b', None)], 'b', '1'),
        ([('a', None)], 'a', {'b': '1'}),
    ]


def test_force_list_callable_receives_parent_path():
    calls = []

    def fl(path, key, value):
        calls.append((list(path), key, value))
        return False

    xmltodict.parse('<a><b>1</b></a>', force_list=fl)
    assert calls == [
        ([('a', None)], 'b', '1'),
        ([], 'a', {'b': '1'}),
    ]


def test_force_cdata_callable_receives_parent_path():
    calls = []

    def fc(path, key, value):
        calls.append((list(path), key, value))
        return False

    assert xmltodict.parse('<a><b>x</b></a>', force_cdata=fc) == {
        'a': {'b': 'x'}}
    assert calls == [([('a', None)], 'b', 'x')]


def test_streaming_force_cdata_tuple_selective():
    seen = []

    def cb(path, item):
        seen.append(item)
        return True

    xmltodict.parse('<a><b>t</b><c>u</c></a>', item_depth=2,
                    item_callback=cb, force_cdata=('b',))
    assert seen == [{'#text': 't'}, 'u']


def test_streaming_force_cdata_callable_receives_parent_path():
    calls = []
    seen = []

    def fc(path, key, value):
        calls.append((list(path), key, value))
        return True

    def cb(path, item):
        seen.append(item)
        return True

    xmltodict.parse('<a><b>t</b></a>', item_depth=2, item_callback=cb,
                    force_cdata=fc)
    assert calls == [([('a', None)], 'b', 't')]
    assert seen == [{'#text': 't'}]


def test_streaming_item_depth_one():
    seen = []

    def cb(path, item):
        seen.append((list(path), item))
        return True

    result = xmltodict.parse('<a><b>1</b></a>', item_depth=1,
                             item_callback=cb)
    assert result is None
    assert seen == [([('a', None)], {'b': '1'})]


def test_streaming_item_depth_one_text_only():
    seen = []
    xmltodict.parse('<a> t </a>', item_depth=1,
                    item_callback=lambda p, i: seen.append(i) or True)
