def test_custom_namespace_separator():
    xml = '<a xmlns:n="u" n:x="1"><n:b>1</n:b></a>'
    doc = xmltodict.parse(xml, process_namespaces=True,
                          namespace_separator='|')
    assert doc == {'a': {'@xmlns': {'n': 'u'}, '@u|x': '1', 'u|b': '1'}}
    doc = xmltodict.parse(xml, process_namespaces=True,
                          namespace_separator='|',
                          namespaces={'u': 'p'})
    assert doc == {'a': {'@xmlns': {'n': 'u'}, '@p|x': '1', 'p|b': '1'}}


