import xml.parsers.expat as _expat_mod

import xmltodict


def test_handler_end_element_at_item_depth_with_empty_stack():
    handler = xmltodict._DictSAXHandler(item_depth=1)
    handler.path = [('a', None)]
    handler.endElement('a')
    assert handler.item is None
    assert handler.data == []
    assert handler.path == []


def test_force_cdata_callable_receives_full_parent_path_nested():
    calls = []

    def fc(path, key, value):
        calls.append((list(path), key, value))
