def test_wait_by_name_fixed_and_no_sleep(sleeps):
    r = Retrying(wait="fixed_sleep", wait_fixed=500, stop_max_attempt_number=3)
    f = Flaky(100)
    with pytest.raises(IOError):
        r.call(f)
    assert sleeps == [0.5, 0.5]

    del sleeps[:]
    r2 = Retrying(wait="no_sleep", stop_max_attempt_number=3)
    g = Flaky(100)
    with pytest.raises(IOError):
        r2.call(g)
    assert sleeps == [0.0, 0.0]


def test_no_sleep_returns_zero():
    assert Retrying.no_sleep(1, 0) == 0
    assert Retrying.no_sleep(10, 5000) == 0


def test_incrementing_sleep_negative_clamped_to_zero():
    r = Retrying(wait_incrementing_start=-1000, wait_incrementing_increment=100)
    assert r.incrementing_sleep(1, 0) == 0
    assert r.incrementing_sleep(5, 0) == 0
    assert r.incrementing_sleep(12, 0) == 100


def test_exponential_sleep_negative_clamped_to_zero():
    r = Retrying(wait_exponential_multiplier=-1)
    assert r.exponential_sleep(1, 0) == 0
    assert r.exponential_sleep(3, 0) == 0


def test_exponential_sleep_values():
    r = Retrying(wait_exponential_multiplier=100, wait_exponential_max=500)
    assert r.exponential_sleep(1, 0) == 200
    assert r.exponential_sleep(2, 0) == 400
    assert r.exponential_sleep(3, 0) == 500


def test_attempt_repr_exception():
    import sys
    try:
        raise KeyError("x")
    except KeyError:
        info = sys.exc_info()
    text = repr(Attempt(info, 4, True))
    assert text.startswith("Attempts: 4, Error:\n")
    assert "KeyError" not in text or isinstance(text, str)
    assert "test_attempt_repr_exception" in text


def test_retry_error_str_with_exception():
    import sys
    try:
        raise ValueError("boom")
    except ValueError:
        info = sys.exc_info()
    a = Attempt(info, 2, True)
    assert str(RetryError(a)) == "RetryError[{0}]".format(repr(a))
